------------ import ------------
local UIModule = CS.Engine.UI.UIModule
------------ import ------------

local UITeamMembersNode = "Game.UI.FightTeam.UITeamMembersNode.UITeamMembersNode"
local cardComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.CardComponent)
local teamComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.TeamComponent)
local UIBattlingTools = import("Game.UI.UIBattling.UIBattlingTools")
local EventDragProxy = CS.Engine.UI.EventDragProxy
local KTool = CS.Engine.Lib.KTool
local RectTransform = CS.UnityEngine.RectTransform
local worldBossComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.WorldBossComponent)

---@class UITeamInfoNode     
---@field BtnMergeSkill                 	UnityEngine.RectTransform               
---@field TextSkillName                 	UnityEngine.RectTransform               
---@field ImgSkillIcon                  	UnityEngine.RectTransform               
---@field PowerText                     	UnityEngine.RectTransform               
---@field UITeamMembersNode             	UnityEngine.RectTransform               
---@field TxtNum                        	UnityEngine.RectTransform               
local UITeamInfoNode = Class('UITeamInfoNode')

function UITeamInfoNode:__init()
    self._data = nil
    self._uiTeamMembersNodeScr = nil  
    self._teamIndex = nil               --队伍下标
    self._curLevelId = nil               --关卡id
    self._curLevelType = nil
    self._autoPos = nil                --默认位置\
    self._allTeamPosInfo = nil         --所有可以交换位置的信息
    self._uiCam = nil
    self._refreshPosCb = nil
end

function UITeamInfoNode:__delete()
    self._data = nil
    self._uiTeamMembersNodeScr = nil  
    self._teamIndex = nil               --队伍下标
    self._curLevelId = nil               --关卡id
    self._curLevelType = nil
    self._autoPos = nil                --默认位置
    self._allTeamPosInfo = nil         --所有可以交换位置的信息
    self._uiCam = nil
    self._refreshPosCb = nil
end

function UITeamInfoNode:Awake()
    if not self._uiFightReardsNodeScr then
        self._uiTeamMembersNodeScr = CfUtils.GetLuaScr(self.UITeamMembersNode, UITeamMembersNode)
    end
    self._uiCam = KTool.FindCameraForLayer(CS.UnityEngine.LayerMask.NameToLayer("UI"))
    self._autoPos = self.controller.gameObject.transform.localPosition

    SetButtonAction(self.BtnMergeSkill, Bind(self, self.OnBtnMergeSkill))
end

function UITeamInfoNode:Refresh(data, levelId, teamIndex)
    if not data then
        return
    end
    self._data = data
    self._teamIndex = teamIndex               --队伍下标
    self._curLevelId = levelId               --关卡id
    self._curLevelType = GoodsUtils.GetIdType(self._curLevelId, Constants.IDArea.Quests)

    local isUnlock, err = QuestConfMgr:GetInstance():IsUnlockTeamByIndex(self._teamIndex)
    KTool.SetActive(self.Lock, not isUnlock)
    KTool.SetActive(self.Normal, isUnlock)
    if isUnlock then
        self:FillTeamMembers()
        self:FillMergeSkillInfo()
    else
        CfUtils.FillText(self.Text, err)
    end
end

function UITeamInfoNode:InitChangePosInfo(allTeamPosInfo, cb)
    self._refreshPosCb = cb
    self._allTeamPosInfo = allTeamPosInfo
    self:InitDrag()
end

--绘制队伍信息
function UITeamInfoNode:FillTeamMembers()
    CfUtils.FillText(self.TxtNum, "#"..checkNumber(self._teamIndex))
    CfUtils.FillText(self.PowerText, teamComponent:GetTeamFightingPower(self._data.cardsInfo))
    local t = {}

    if self._data.cardsInfo then
        for k, v in pairs(self._data.cardsInfo) do
            local data = cardComp:GetCardById(v.refId) 
            table.insert(t, data)
        end
    end

    if self._uiTeamMembersNodeScr then
        local upBuffData = {}
        local id = worldBossComponent:GetCurBossPlanId()
        local vo = QuestConfMgr:GetInstance():GetWorldBossPlanVo(id)
        if vo then
            local upBuffVos = QuestConfMgr:GetInstance():GetWorldBossUpData(vo.UpGroup)
            if upBuffVos then
                upBuffData = QuestConfMgr:GetInstance():GetAllUpDataByVos(upBuffVos)
            end
        end

        self._uiTeamMembersNodeScr:Refresh(t, true, 0.7, function()
            if self._curLevelType == Constants.IDType.QuestWorldBoss then
                local isUnlock, err = QuestConfMgr:GetInstance():IsUnlockTeamByIndex(self._teamIndex)
                if not isUnlock then
                    GameUtils.Toast(err)
                    return
                end
            end
            
            local excludeDialogs = self.excludeDialogs or {
                { id = Constants.UITypeIds.UIWorldBossFormationDialog}
            }
            UIModule.OpenDialog({id = Constants.UITypeIds.UIFightTeamCardChoose, parameters = {levelId = self._curLevelId, teamIndex = self._teamIndex, upBuffData = upBuffData}}, excludeDialogs)
        end, nil, upBuffData)
    end
end

--绘制合卡技
function UITeamInfoNode:FillMergeSkillInfo()
    local mergeSkillId = checkNumber(self._data.mergeSkill)
    if mergeSkillId == 0 then
        mergeSkillId = QuestConfMgr:GetInstance():GetAutoMergeSkillId()
    end

    local vo = QuestConfMgr:GetInstance():GetMergeSkillVo(mergeSkillId)
    if not vo then
        return
    end
    CfUtils.FillImage(self.ImgSkillIcon, vo.photoPath)

    if vo then
        local skillVo = UIBattlingTools.GetSkillCardInfoBySkillId(vo.skillId, 1)
        if skillVo then
            CfUtils.FillText(self.TextSkillName, skillVo.skillName)
        end
    end
end

function UITeamInfoNode:InitDrag()
    local isUnlock, err = QuestConfMgr:GetInstance():IsUnlockTeamByIndex(self._teamIndex)
    if not isUnlock then
        return    
    elseif not self._allTeamPosInfo then
        return
    end

    local drag = EventDragProxy.Create(self.controller.gameObject)
    drag.onPointerBeginDrag = Bind(self, self.OnBeginDrag)
    drag.onPointerDrag = Bind(self, self.OnDrag)
    drag.onPointerEndDrag = Bind(self, self.OnEndDrag)
end


function UITeamInfoNode:OnBeginDrag(eventData)
    if isNull(eventData) then return end
end

---@param eventData UnityEngine.EventSystems.PointerEventData
function UITeamInfoNode:OnDrag(eventData)
    if isNull(eventData) then return end
    local pos = eventData.delta
    self:RefreshPos(self.controller.gameObject.transform.localPosition + Vector3(pos.x, pos.y, 0))
end

function UITeamInfoNode:OnEndDrag(eventData)
    if isNull(eventData) then return end
    for k, v in pairs(self._allTeamPosInfo) do
        local isUnlock, err = QuestConfMgr:GetInstance():IsUnlockTeamByIndex(v.teamIndex)
        --解锁才交换
        if isUnlock and v.teamIndex ~= self._teamIndex and self._uiCam then
            local rect = v.go.transform:GetComponent(typeof(RectTransform))
            local pos = self.controller.transform.position
            local isChange = CS.UnityEngine.RectTransformUtility.RectangleContainsScreenPoint(rect, Vector2(pos.x, pos.y))
            if isChange then
                local t1 = clone(teamComponent:GetTeamInfoByQuestId(self._curLevelId, self._teamIndex))
                local t2 = clone(teamComponent:GetTeamInfoByQuestId(self._curLevelId, v.teamIndex))
                teamComponent:SetTeamByQuestId(self._curLevelId, t1.cardsInfo, nil, v.teamIndex)
                teamComponent:SetTeamByQuestId(self._curLevelId, t2.cardsInfo, nil, self._teamIndex)

                self:RefreshPos(self._autoPos)
                if self._refreshPosCb then
                    self._refreshPosCb()
                end
                return
            end
        end
    end
    self:RefreshPos(self._autoPos)
end

--刷新位置
function UITeamInfoNode:RefreshPos(pos)
    if not pos then
        return nil
    end
    self.controller.gameObject.transform.localPosition = pos
end

function UITeamInfoNode:SetExcludeDialogs(excludeDialogs)
    self.excludeDialogs = excludeDialogs
end

--合卡技界面
function UITeamInfoNode:OnBtnMergeSkill()
    if self._curLevelType == Constants.IDType.QuestWorldBoss then
        local isUnlock, err = QuestConfMgr:GetInstance():IsUnlockTeamByIndex(self._teamIndex)
        if not isUnlock then
            GameUtils.Toast(err)
            return
        end
    end
    UIModule.OpenDialog({ id = Constants.UITypeIds.UISkillCompoundDialog, parameters = {levelId = self._curLevelId, teamIndex = self._teamIndex}})
end

function UITeamInfoNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UITeamInfoNode
